import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Science User Group Meetup - March 2026","description":"","frontmatter":{"title":"Ceph Science User Group Meetup - March 2026","date":"2026-06-11T00:00:00.000Z","updated":"2026-06-12T00:00:00.000Z","tags":["Ceph","RGW","对象存储","社区动态","会议纪要"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Science_User_Group_Meetup_-_March_2026.md","filePath":"posts/2026/Ceph_Science_User_Group_Meetup_-_March_2026.md","lastUpdated":null}'),t={name:"posts/2026/Ceph_Science_User_Group_Meetup_-_March_2026.md"};function o(n,e,s,c,u,h){return l(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ceph-science-user-group-meetup-march-2026-会议纪要" tabindex="-1">Ceph Science User Group Meetup - March 2026 会议纪要 <a class="header-anchor" href="#ceph-science-user-group-meetup-march-2026-会议纪要" aria-label="Permalink to &quot;Ceph Science User Group Meetup - March 2026 会议纪要&quot;">​</a></h1><p>本次 Ceph Science User Group 月度聚会延续了往常非正式讨论的形式，社区成员围绕集群升级经验、混合容量磁盘的 balancer 行为、超算环境下 S3/RGW 的使用模式、Pacific 到 Reef 升级中的 deprecated connection feature bit 问题、RGW 对外网暴露的安全实践以及向 Ceph 社区贡献代码的途径等话题展开了交流。</p><h2 id="一、集群升级经验分享" tabindex="-1">一、集群升级经验分享 <a class="header-anchor" href="#一、集群升级经验分享" aria-label="Permalink to &quot;一、集群升级经验分享&quot;">​</a></h2><h3 id="_1-reef-小版本升级" tabindex="-1">1. Reef 小版本升级 <a class="header-anchor" href="#_1-reef-小版本升级" aria-label="Permalink to &quot;1. Reef 小版本升级&quot;">​</a></h3><p>一位与会者分享了近期完成的 Reef 系列内的小版本升级经验，从 18.2.6 升级到 18.2.7（或 18.2.8）。该升级通过 Cephadm 完成，整体过程顺利。该用户强调自己在升级前会投入大量时间做准备工作，因此到目前为止所有升级几乎都很平稳。</p><h3 id="_2-升级到-tentacle-的计划" tabindex="-1">2. 升级到 Tentacle 的计划 <a class="header-anchor" href="#_2-升级到-tentacle-的计划" aria-label="Permalink to &quot;2. 升级到 Tentacle 的计划&quot;">​</a></h3><ul><li>主持人计划在下次会议前将测试集群升级到 Tentacle，目前生产集群仍在 Squid。</li><li>部分用户的测试集群目前借给了内部团队评估 Rook 与 Cephadm 的使用体验，因此尚未着手 Tentacle 升级。</li><li>也有用户卡在 Quincy 上，正在规划升级到 Squid，暂无更进一步升级计划。</li><li>普遍共识是不急于上 Tentacle 生产，至少先在测试环境跑一段时间。</li></ul><h3 id="_3-发布节奏" tabindex="-1">3. 发布节奏 <a class="header-anchor" href="#_3-发布节奏" aria-label="Permalink to &quot;3. 发布节奏&quot;">​</a></h3><p>社区确认 Ceph 仍维持以下发布节奏：</p><ul><li>每年一个大版本（Major release）。</li><li>维持 N-2 的支持窗口。</li><li>期间发布 patch release，新版本 N+2 发布后，最后一个 patch 即为 EOL。</li></ul><h2 id="二、rgw-集群规划与多容量磁盘的-balancer-行为" tabindex="-1">二、RGW 集群规划与多容量磁盘的 balancer 行为 <a class="header-anchor" href="#二、rgw-集群规划与多容量磁盘的-balancer-行为" aria-label="Permalink to &quot;二、RGW 集群规划与多容量磁盘的 balancer 行为&quot;">​</a></h2><h3 id="_1-集群现状与新业务上线" tabindex="-1">1. 集群现状与新业务上线 <a class="header-anchor" href="#_1-集群现状与新业务上线" aria-label="Permalink to &quot;1. 集群现状与新业务上线&quot;">​</a></h3><p>某站点目前主要的工作负载为 radosgw / S3，仅有少量 RBD。其中一个 OpenStack RBD 集群从 2017 年运行至上周才下线，期间最大问题来自 Nautilus 升级时的一次操作失误，但整体提供了八到九年的稳定服务。</p><p>正在进行的工作：</p><ul><li>在已有的主 RGW 集群（约两千个 OSD，约 22 PB）上为另一组用户启动<strong>第二个 S3 服务</strong>。</li><li>第二个服务将使用<strong>独立的 RGW 集群</strong>与<strong>外部 Keystone</strong>，并跨全国实现联邦化（federated service）。</li><li>数据池采用<strong>独立的 pool</strong>，新业务规模约 2 PB，与既有 22 PB 的数据共享同一组 HDD。</li></ul><p>由此引出对 balancer 行为的关注。</p><h3 id="_2-异构磁盘容量下的-balancing" tabindex="-1">2. 异构磁盘容量下的 balancing <a class="header-anchor" href="#_2-异构磁盘容量下的-balancing" aria-label="Permalink to &quot;2. 异构磁盘容量下的 balancing&quot;">​</a></h3><p>讨论的核心问题：当冷备磁盘与在用磁盘容量不同（例如冷备为 14 TB，在用为 16 TB）时，CRUSH 与 balancer 是否仍能保持均衡？</p><p>要点：</p><ul><li>容量差异在 CRUSH 中通过 <strong>crush weight</strong> 自然反映，集群在节点层面通过加权处理，可以兼容长期存在的多代磁盘混用（8/10/12/14/16 TB）。</li><li>通过 <code>ceph df</code> 可以观察两个关键的 fullness 数值： <ul><li>存储类（如 HDD storage class）的整体 percentage full；</li><li>关键 pool（如 <code>buckets.data</code> pool）的 percentage full。</li></ul></li><li>两者之间通常存在 3% 到 5% 左右的差异；当集群发生大规模磁盘损坏或新增节点时，该差异会显著放大，再缓慢收敛。</li><li>一位用户在完全同构（全部 16 TB）的环境中观察到约 4.5% 的差距，被认为是相当不错的水平。</li></ul><h3 id="_3-percentage-full-的计算细节" tabindex="-1">3. percentage full 的计算细节 <a class="header-anchor" href="#_3-percentage-full-的计算细节" aria-label="Permalink to &quot;3. percentage full 的计算细节&quot;">​</a></h3><p>有成员补充说明：percentage full 的计算大致基于「<strong>单设备最小可用空间</strong> × <strong>构成 pool 的设备数量</strong>」。当混用大小差异显著的磁盘（例如 2 TB 与 16 TB），最小可用空间会主导该指标，使其作为 fullness 指示的意义被削弱，但仍是判断「最坏情况下何时会被打爆」的有用参考。</p><h3 id="_4-balancer-调优建议" tabindex="-1">4. balancer 调优建议 <a class="header-anchor" href="#_4-balancer-调优建议" aria-label="Permalink to &quot;4. balancer 调优建议&quot;">​</a></h3><p>对于希望进一步收紧分布的集群：</p><ul><li>默认 balancer 允许的 OSD 间偏差大约为 5（个 PG）。</li><li>可将该偏差参数下调至 1，从而强制 balancer 做更精细的均衡。</li><li>一位用户表示通过这一调优手段，使其集群相比两年前在 balance 与稳定性方面有了根本改观，这对其上层 RGW 服务的稳定运行非常关键。</li></ul><p>会上请分享相关参数的成员将具体配置项贴入了 etherpad 以便事后参考。</p><h2 id="三、超算环境中的-s3-rgw-实践" tabindex="-1">三、超算环境中的 S3/RGW 实践 <a class="header-anchor" href="#三、超算环境中的-s3-rgw-实践" aria-label="Permalink to &quot;三、超算环境中的 S3/RGW 实践&quot;">​</a></h2><h3 id="_1-rgw-作为「超算存储」的定位" tabindex="-1">1. RGW 作为「超算存储」的定位 <a class="header-anchor" href="#_1-rgw-作为「超算存储」的定位" aria-label="Permalink to &quot;1. RGW 作为「超算存储」的定位&quot;">​</a></h3><p>有站点同时运行 Lustre 与 Ceph RGW，并明确将 <strong>Ceph RGW 集群定位为超算存储（supercomputing storage）</strong>：</p><ul><li>Lustre 作为 scratch / job 文件系统。</li><li>鼓励研究人员将数据<strong>长期存放在 S3/RGW</strong>，使用时再通过 Slurm 作业从 S3 拉到 Lustre 上参与计算，结果再写回 S3。</li><li>这种模式正在被超算技术后端运维与一线用户支持团队接受，将 S3 视为正式的「超算存储」，即便它并非高速并行文件系统。</li></ul><h3 id="_2-推动-s3-在超算中替代-posix" tabindex="-1">2. 推动 S3 在超算中替代 POSIX <a class="header-anchor" href="#_2-推动-s3-在超算中替代-posix" aria-label="Permalink to &quot;2. 推动 S3 在超算中替代 POSIX&quot;">​</a></h3><p>另一位用户的环境中拥有约 150 PB 的 IBM GPFS 文件系统，目前还在思考如何在下一代（4–5 年后）超算采购中引入 S3 存储。讨论中提到说服用户使用 S3 的几个常见论据：</p><ul><li><strong>Scratch 有清理策略</strong>：scratch 上的数据迟早会被 purge，真正想长期保存的数据本就该放在持久存储上。</li><li><strong>数据原地共享</strong>：S3 中的数据可以通过 bucket policy 或 pre-signed URL 直接对外提供，无需额外搬运，天然适配数据共享场景。</li><li><strong>更好的 resilience</strong>：通过适当的 replication / erasure coding profile，可以在持久性上获得很高的保障。</li><li><strong>跨机构数据流转</strong>：可借助 <strong>Globus</strong> 在 scratch 文件系统与 S3 之间，以及与其他研究机构间转移数据，S3 作为目的地提供了「到达即安全」的特性。</li></ul><h3 id="_3-用户体验工程-从密钥到-slurm-作业模板" tabindex="-1">3. 用户体验工程：从密钥到 Slurm 作业模板 <a class="header-anchor" href="#_3-用户体验工程-从密钥到-slurm-作业模板" aria-label="Permalink to &quot;3. 用户体验工程：从密钥到 Slurm 作业模板&quot;">​</a></h3><p>为降低研究人员使用 S3 的门槛，该站点提供了介于「全程 hand-holding」与「完全 DIY」之间的一套支撑：</p><ul><li>通过自研的 Django 项目管理门户（与 LDAP 集成）签发 S3 keys： <ul><li>首次生成时一次性显示 secret key，之后不再展示；</li><li>支持新建、删除 keys，并区分项目级与个人配额。</li></ul></li><li>文档中提供： <ul><li>S3 客户端选择建议（计划在 Globus 上线后纳入文档）；</li><li>直接可拷贝到 <code>rclone.conf</code> 或 AWS 配置中的片段；</li><li>put / get / mb 等基础命令示例；</li><li><strong>Slurm 作业模板</strong>：一个典型流程被拆成三个 Slurm 作业，依次完成「拉数据 → 真实计算/GPU 作业 → 回写结果」，并配合 21 天 scratch purge 策略。</li></ul></li></ul><h3 id="_4-项目级与个人级权限模型" tabindex="-1">4. 项目级与个人级权限模型 <a class="header-anchor" href="#_4-项目级与个人级权限模型" aria-label="Permalink to &quot;4. 项目级与个人级权限模型&quot;">​</a></h3><p>该站点观察到，许多研究组通过 Keystone 与 LDAP group 关联到 S3 项目，但默认的「LDAP 组成员皆能访问全部 bucket」对 PI 或管理员来说粒度太粗。为此引入了<strong>个人配额（individual allocation）方案</strong>：</p><ul><li>移除组级成员关系，仅给 PI 与管理员保留个人级访问；</li><li>通过特定的 rclone / AWS flags 配合 bucket policy，将权限下放到具体 PhD 学生或合作者；</li><li>同时也提到目前仍重度依赖 ACL，但 Casey Bodley 此前在会议上提到主线分支已经具备<strong>取代 ACL 的新特性</strong>，预计在未来版本（可能是 UEbu 之后，目前未在 Tentacle 中发布）落地，届时权限模型有望进一步简化。</li></ul><h3 id="_5-推广中的挑战" tabindex="-1">5. 推广中的挑战 <a class="header-anchor" href="#_5-推广中的挑战" aria-label="Permalink to &quot;5. 推广中的挑战&quot;">​</a></h3><p>普遍认为 S3 推广的最大阻力来自用户端的认知与工作流改造：</p><ul><li>用户长期使用 POSIX 思维，需要重新理解对象存储模型；</li><li>对应的文档、工具链、Slurm 模板必须保持一致；</li><li>例如该团队为图形化 bucket policy 管理工具新增了简单 policy 支持，但因措辞问题让部分用户产生困惑，凸显了一致性表述的重要性。</li></ul><h2 id="四、pacific-→-reef-升级中的-deprecated-connection-feature-bit" tabindex="-1">四、Pacific → Reef 升级中的 Deprecated Connection Feature Bit <a class="header-anchor" href="#四、pacific-→-reef-升级中的-deprecated-connection-feature-bit" aria-label="Permalink to &quot;四、Pacific → Reef 升级中的 Deprecated Connection Feature Bit&quot;">​</a></h2><h3 id="_1-问题背景" tabindex="-1">1. 问题背景 <a class="header-anchor" href="#_1-问题背景" aria-label="Permalink to &quot;1. 问题背景&quot;">​</a></h3><p>有成员阅读 18.2.8 的 release notes 时注意到一段说明：在从 Pacific 升级到 Reef 的过程中，Ceph 重用了一个原本应被废弃的 <strong>connection feature bit</strong> 来标识 Reef OSD，这导致：</p><ul><li>在所有 OSD 实际完成升级到 Reef <strong>之前</strong>，集群可能就出现「OSD 升级完成」的告警。</li><li>该 bit 的语义与最初设计的用途不一致，此问题由 Patrick 发现并提出。</li></ul><h3 id="_2-影响评估" tabindex="-1">2. 影响评估 <a class="header-anchor" href="#_2-影响评估" aria-label="Permalink to &quot;2. 影响评估&quot;">​</a></h3><p>社区目前的初步看法：</p><ul><li>一旦所有 OSD 全部升级到 Reef，该「Pacific 视角下的 bit 含义」即不再存在，因此<strong>完成升级后的稳态系统应当不受影响</strong>；</li><li>真正存在风险的是 <strong>Pacific 与 Reef OSD 共存的过渡期</strong>，在该窗口期内若 Ceph 写数据的路径行为出现异常，则可能埋下问题；</li><li>release notes 中以「过度谨慎」的口吻<strong>不再推荐从 Pacific 直接升级到 Reef</strong>。</li></ul><h3 id="_3-用户侧的疑虑" tabindex="-1">3. 用户侧的疑虑 <a class="header-anchor" href="#_3-用户侧的疑虑" aria-label="Permalink to &quot;3. 用户侧的疑虑&quot;">​</a></h3><p>已经完成 Pacific → Reef 升级的用户对此提出更深层的担忧：</p><ul><li>仅靠 release notes 难以判断该 feature bit 是否仅在升级路径中被使用，是否在其他代码路径下还有残留语义；</li><li>如果该 bit 在其它场景被误用，则可能在某些边界条件下出现「未被发现的副作用」；</li><li>当前看来类似「检查发动机灯」式的告警：知道有问题，但具体是否需要动手处理仍不明朗。</li></ul><h3 id="_4-后续行动建议" tabindex="-1">4. 后续行动建议 <a class="header-anchor" href="#_4-后续行动建议" aria-label="Permalink to &quot;4. 后续行动建议&quot;">​</a></h3><ul><li>鼓励受影响的用户<strong>在 ceph-users 邮件列表上进一步反馈</strong>，以便核心开发者评估是否需要补充 workaround 或 dev 工作；</li><li>在 etherpad 中保留相关邮件链接，便于之后跟踪。</li></ul><h2 id="五、rgw-对外网暴露的安全实践" tabindex="-1">五、RGW 对外网暴露的安全实践 <a class="header-anchor" href="#五、rgw-对外网暴露的安全实践" aria-label="Permalink to &quot;五、RGW 对外网暴露的安全实践&quot;">​</a></h2><p>围绕「如何把 radosgw 安全地暴露到公网」的话题，多位与会者分享了各自的部署模型。</p><h3 id="_1-haproxy-tls-keystone-模式" tabindex="-1">1. HAProxy + TLS + Keystone 模式 <a class="header-anchor" href="#_1-haproxy-tls-keystone-模式" aria-label="Permalink to &quot;1. HAProxy + TLS + Keystone 模式&quot;">​</a></h3><ul><li>前端使用 HAProxy 终结 TLS；</li><li>由于此前 Keystone 出现过一个理论性的安全漏洞，该站点已禁用 5000 端口的直接访问，等待升级到更新版本；</li><li>与 Cephadm 集群配合使用，HAProxy 与 keepalived 看上去很可能是 Cephadm 自带的（容器名中带 fs ID / cluster ID 是典型 Cephadm 风格）。</li></ul><h3 id="_2-kubernetes-ingress-物理-rgw-节点" tabindex="-1">2. Kubernetes Ingress + 物理 RGW 节点 <a class="header-anchor" href="#_2-kubernetes-ingress-物理-rgw-节点" aria-label="Permalink to &quot;2. Kubernetes Ingress + 物理 RGW 节点&quot;">​</a></h3><ul><li>公司级防火墙之后部署 Kubernetes 集群，使用 Kubernetes Ingress；</li><li>HAProxy 在 RGW 节点之间做负载均衡，RGW 本体仍部署在物理机上；</li><li>已稳定运行约 3 年，承载了<strong>约 17 个域名 / 多个项目</strong>；</li><li>借助 Let&#39;s Encrypt 自动签发证书，TLS 证书管理非常省心；</li><li>该方案被视为可扩展（scalable）且易于运维的模式。</li></ul><h3 id="_3-keepalived-dns-round-robin" tabindex="-1">3. keepalived + DNS round robin <a class="header-anchor" href="#_3-keepalived-dns-round-robin" aria-label="Permalink to &quot;3. keepalived + DNS round robin&quot;">​</a></h3><ul><li>通过 keepalived 管理多个 IP 地址；</li><li>多个 IP 通过 DNS round robin 暴露给客户端；</li><li>这一做法被观察到带来了显著的性能提升。</li></ul><h3 id="_4-共识" tabindex="-1">4. 共识 <a class="header-anchor" href="#_4-共识" aria-label="Permalink to &quot;4. 共识&quot;">​</a></h3><ul><li>RGW 作为 S3 服务对外暴露在安全层面与「将任意服务对外暴露」并无本质区别；</li><li>关键在于与公司安全 / 网络团队对齐，使用合规的网络设备与 TLS 实践；</li><li>多数团队倾向于通过 HAProxy / Ingress 等成熟组件来分担安全与负载均衡的复杂度。</li></ul><h2 id="六、社区贡献与开发者参与方式" tabindex="-1">六、社区贡献与开发者参与方式 <a class="header-anchor" href="#六、社区贡献与开发者参与方式" aria-label="Permalink to &quot;六、社区贡献与开发者参与方式&quot;">​</a></h2><p>一位与会者表示其团队中有一位空闲的开发者，希望参与到 RGW 的修复工作中，询问推荐的贡献路径。社区给出的建议如下：</p><ul><li><strong>从 standup / 会议入手</strong>：Ceph 各 SIG 与团队的 standup 都是公开的，建议该开发者先加入相关会议，了解 RGW 团队的工作分发与 review 流程，然后再尝试提交 merge request；</li><li>若直接「冷启动」提交 PR，往往优先级较低；先建立熟悉度，会更容易让 PR 被接纳；</li><li><strong>Ceph 性能 SIG</strong> 等 weekly meeting 氛围非常友好，对希望了解性能议题的人来说也是不错的入口；</li><li>Ceph 官网提供了完整的 <strong>community calendar</strong>，将其导入工作日历后会发现 Ceph 社区一周排满了各种会议；</li><li>推荐加入 Ceph Slack 的 <strong><code>ceph-devel</code> channel</strong>，相关链接已在会议聊天中分享。</li></ul><h2 id="七、决议事项" tabindex="-1">七、决议事项 <a class="header-anchor" href="#七、决议事项" aria-label="Permalink to &quot;七、决议事项&quot;">​</a></h2><ol><li>对从 Pacific 升级到 Reef 时遇到的 deprecated connection feature bit 问题，<strong>短期保持观察</strong>；已升级用户被建议向 ceph-users 邮件列表反馈以便核心团队评估。</li><li>对于 RGW 集群中新增 S3 服务的规划，<strong>采用独立的 pool 与独立的 RGW，外部 Keystone 提供联邦认证</strong>，并依赖 CRUSH weight + balancer 处理在共享 HDD 上的容量再平衡。</li><li>balancer 偏差参数（默认偏差约为 5 个 OSD/PG）可下调至 1，<strong>用于在已有较好基础上进一步收紧分布</strong>。</li><li><strong>不急于在生产上 Tentacle</strong>：先在测试集群验证后再做规划。</li><li>鼓励希望参与 Ceph 开发的工程师<strong>先加入公开会议、再提交 PR</strong>，并通过 <code>ceph-devel</code> Slack channel 与社区互动。</li></ol><h2 id="八、后续行动计划" tabindex="-1">八、后续行动计划 <a class="header-anchor" href="#八、后续行动计划" aria-label="Permalink to &quot;八、后续行动计划&quot;">​</a></h2><ul><li><strong>测试集群升级</strong>：主持人计划在下次会议（5 月 26 日）前将测试集群升级到 Tentacle，并在下次会议中分享体验。</li><li><strong>第二个 S3 服务上线准备</strong>：拥有 22 PB RGW 集群的团队继续推进新增 2 PB S3 服务的部署，关注新旧 pool 共享 HDD 时的 balancer 行为；同时计划继续从 Reef 推进到 Squid。</li><li><strong>跟进 Pacific → Reef feature bit 问题</strong>：相关用户将在邮件列表跟进确认，是否需要任何 workaround 或额外处理。</li><li><strong>超算 + S3 推广</strong>：相关站点将持续完善文档、客户端配置范例与 Slurm 模板，并在 Globus 上线后纳入文档；同时关注未来版本中「替代 ACL 的 bucket policy 新特性」的发布节奏，以简化项目级与个人级权限管理。</li><li><strong>RGW 公网暴露评估</strong>：尚未对外暴露 RGW 的团队将与各自的安全团队评估外部访问方案，参考 HAProxy + Keystone、Kubernetes Ingress + Let&#39;s Encrypt、keepalived + DNS round robin 等模式。</li><li><strong>下一次会议</strong>：定于 <strong>2026 年 5 月 26 日</strong>举行。</li></ul>',71)])])}const g=a(t,[["render",o]]);export{p as __pageData,g as default};
